                    .intent("EXPLAIN_AI")
                    .status("INFO")
                    .timestamp(now)
                    .build();
        }

        // Generic intelligent fallback
        return AiChatResponse.builder()
                .reply("Hello! I am your **QVS Agentic AI Assistant**. You can ask me to:\n\n"
                        + "• Check specific certificates (e.g., *'Check Sarah Jenkins'* or *'Verify QVS-2024-BSC-8891'*)\n"
                        + "• Explain how the **Blockchain Ledger** ensures zero tampering\n"
                        + "• Inspect **AI Fraud Risk** rules and anomaly scoring")
                .intent("GENERAL_ASSIST")
                .status("INFO")
                .timestamp(now)
                .build();
    }
