:root {
    --primary: #2563eb;
    --primary-gradient: linear-gradient(135deg, #2563eb 0%, #4f46e5 100%);
    --primary-dark: #1d4ed8;
    --primary-light: #60a5fa;
    --secondary: #0f172a;
    --accent: #10b981;
    --danger: #ef4444;
    --warning: #f59e0b;
    --bg-main: #f8fafc;
    --card-bg: #ffffff;
    --text-main: #0f172a;
    --text-muted: #64748b;
    --border: #e2e8f0;
    --border-dark: #cbd5e1;
    --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
    --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
    --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
    --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04);
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-family: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
}

body {
    background-color: var(--bg-main);
    color: var(--text-main);
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    overflow-x: hidden;
}

.font-mono {
    font-family: 'JetBrains Mono', monospace !important;
}

/* Announcement Header */
.top-announcement {
    background: #0f172a;
    color: #94a3b8;
    font-size: 0.8rem;
    text-align: center;
    padding: 0.4rem 1rem;
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.top-announcement strong {
    color: #38bdf8;
}

/* Navbar */
.navbar {
    background: rgba(15, 23, 42, 0.95);
    backdrop-filter: blur(10px);
    position: sticky;
    top: 0;
    z-index: 100;
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.nav-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0.85rem 1.5rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.nav-brand {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    text-decoration: none;
    color: white;
}

.brand-logo {
    font-size: 1.5rem;
    background: linear-gradient(135deg, #3b82f6, #6366f1);
    width: 40px;
    height: 40px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 10px;
    box-shadow: 0 4px 10px rgba(59, 130, 246, 0.3);
}

.brand-title {
    font-size: 1.15rem;
    font-weight: 800;
    letter-spacing: -0.02em;
    display: block;
}

.brand-subtitle {
    font-size: 0.7rem;
    color: #94a3b8;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    display: block;
}

.nav-menu {
    display: flex;
    align-items: center;
    gap: 1.5rem;
}

.nav-link {
    color: #cbd5e1;
    text-decoration: none;
    font-size: 0.9rem;
    font-weight: 500;
    transition: color 0.2s;
}

.nav-link:hover, .nav-link.active {
    color: #38bdf8;
}

.nav-auth {
    margin-left: 0.5rem;
}

.nav-toggle {
    display: none;
    background: none;
    border: none;
    cursor: pointer;
    flex-direction: column;
    gap: 5px;
}

.nav-toggle span {
    display: block;
    width: 24px;
    height: 2px;
    background: white;
}

/* Hero Section */
.hero-section {
    position: relative;
    background: radial-gradient(circle at 50% -20%, #1e293b 0%, #0f172a 100%);
    color: white;
    padding: 4.5rem 1.5rem 5.5rem;
    text-align: center;
    overflow: hidden;
}

.hero-bg-glow {
    position: absolute;
    top: 20%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 600px;
    height: 300px;
    background: radial-gradient(circle, rgba(59, 130, 246, 0.25) 0%, rgba(15, 23, 42, 0) 70%);
    pointer-events: none;
}

.hero-content {
    position: relative;
    z-index: 2;
    max-width: 900px;
    margin: 0 auto;
}

.hero-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    background: rgba(59, 130, 246, 0.15);
    border: 1px solid rgba(59, 130, 246, 0.35);
    padding: 0.35rem 1rem;
    border-radius: 9999px;
    font-size: 0.8rem;
    font-weight: 600;
    color: #60a5fa;
    margin-bottom: 1.5rem;
}

.pulse-dot {
    width: 8px;
    height: 8px;
    background: #10b981;
    border-radius: 50%;
    box-shadow: 0 0 8px #10b981;
    animation: pulse 2s infinite;
}

@keyframes pulse {
    0%, 100% { transform: scale(1); opacity: 1; }
    50% { transform: scale(1.3); opacity: 0.6; }
}

.hero-title {
    font-size: 3rem;
    font-weight: 800;
    line-height: 1.15;
    letter-spacing: -0.03em;
    margin-bottom: 1.25rem;
}

.text-gradient {
    background: linear-gradient(135deg, #60a5fa 0%, #a78bfa 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.hero-description {
    font-size: 1.15rem;
    color: #94a3b8;
    line-height: 1.6;
    max-width: 720px;
    margin: 0 auto 2.5rem;
}

/* Search Card */
.search-box-wrapper {
    max-width: 750px;
    margin: 0 auto;
}

.search-card {
    background: rgba(255, 255, 255, 0.98);
    color: var(--text-main);
    border-radius: 20px;
    padding: 2rem;
    box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.25);
    border: 1px solid rgba(255, 255, 255, 0.2);
    text-align: left;
}

.search-card-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.search-label {
    font-size: 0.95rem;
    font-weight: 700;
    color: #1e293b;
}

.search-hint {
    font-size: 0.75rem;
    color: #64748b;
}

.input-group {
    display: flex;
    gap: 0.75rem;
    margin-bottom: 1.25rem;
}

.input-control {
    flex: 1;
    padding: 0.9rem 1.25rem;
    border: 2px solid var(--border);
    border-radius: 12px;
    font-size: 1rem;
    outline: none;
    transition: all 0.2s;
    background: #f8fafc;
}

.input-control:focus {
    border-color: var(--primary);
    background: #ffffff;
    box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.1);
}

.btn-primary {
    background: var(--primary-gradient);
    color: white;
    padding: 0.9rem 1.75rem;
    border: none;
    border-radius: 12px;
    font-size: 0.95rem;
    font-weight: 700;
    cursor: pointer;
    transition: all 0.2s;
    box-shadow: 0 4px 12px rgba(37, 99, 235, 0.25);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.5rem;
    text-decoration: none;
}

.btn-primary:hover {
    transform: translateY(-1px);
    box-shadow: 0 6px 16px rgba(37, 99, 235, 0.35);
}

.btn-primary.btn-sm {
    padding: 0.5rem 1rem;
    font-size: 0.85rem;
    border-radius: 8px;
}

.btn-outline {
    background: transparent;
    border: 1px solid var(--border-dark);
    color: #334155;
    padding: 0.5rem 1rem;
    border-radius: 8px;
    font-weight: 600;
    font-size: 0.85rem;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-outline:hover {
    background: #f1f5f9;
    border-color: #94a3b8;
}

.btn-outline.btn-sm {
    padding: 0.4rem 0.8rem;
    font-size: 0.8rem;
}

/* Quick Test Bar */
.quick-test-bar {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.5rem;
    font-size: 0.8rem;
}

.quick-test-label {
    color: #64748b;
    font-weight: 600;
}

.chip-btn {
    padding: 0.35rem 0.75rem;
    border-radius: 20px;
    font-size: 0.78rem;
    font-weight: 600;
    cursor: pointer;
    border: none;
    transition: all 0.2s;
}

.chip-success {
    background: #dcfce7;
    color: #15803d;
    border: 1px solid #bbf7d0;
}

.chip-success:hover {
    background: #bbf7d0;
}

.chip-danger {
    background: #fee2e2;
    color: #b91c1c;
    border: 1px solid #fecaca;
}

.chip-danger:hover {
    background: #fecaca;
}

.chip-neutral {
    background: #f1f5f9;
    color: #475569;
    border: 1px solid #e2e8f0;
}

.chip-neutral:hover {
    background: #e2e8f0;
}

/* Loading Box */
.loading-box {
    margin: 2rem auto;
    text-align: center;
    color: #93c5fd;
    font-size: 0.95rem;
}

.spinner {
    width: 36px;
    height: 36px;
    border: 4px solid rgba(255, 255, 255, 0.2);
    border-top-color: #60a5fa;
    border-radius: 50%;
    animation: spin 0.8s linear infinite;
    margin: 0 auto 0.75rem;
}

@keyframes spin {
    to { transform: rotate(360deg); }
}

/* Result Card */
.result-card {
    background: white;
    color: var(--text-main);
    border-radius: 20px;
    padding: 2.25rem;
    box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.3);
    border-left: 8px solid var(--accent);
    margin-top: 2rem;
    text-align: left;
    animation: slideUp 0.3s ease-out;
}

@keyframes slideUp {
    from { opacity: 0; transform: translateY(15px); }
    to { opacity: 1; transform: translateY(0); }
}

.result-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    padding-bottom: 1.25rem;
    border-bottom: 1px solid var(--border);
    margin-bottom: 1.5rem;
}

.result-eyebrow {
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #64748b;
    font-weight: 700;
    display: block;
    margin-bottom: 0.25rem;
}

.result-title {
    font-size: 1.5rem;
    font-weight: 800;
    color: #0f172a;
}

.result-desc {
    color: #475569;
    font-size: 0.95rem;
    margin-top: 0.25rem;
}

.status-badge {
    padding: 0.5rem 1.25rem;
    border-radius: 9999px;
    font-weight: 800;
    font-size: 0.85rem;
    letter-spacing: 0.05em;
    text-transform: uppercase;
}

.status-badge-success {
    background: #dcfce7;
    color: #15803d;
    border: 1px solid #bbf7d0;
}

.status-badge-danger {
    background: #fee2e2;
    color: #b91c1c;
    border: 1px solid #fecaca;
}

.status-badge-warning {
    background: #fef3c7;
    color: #b45309;
    border: 1px solid #fde68a;
}

.credential-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 1.25rem;
    margin-bottom: 1.5rem;
}

.data-card {
    background: #f8fafc;
    padding: 1rem;
    border-radius: 12px;
    border: 1px solid var(--border);
}

.data-label {
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: #64748b;
    font-weight: 700;
    display: block;
    margin-bottom: 0.25rem;
}

.data-value {
    font-size: 1.05rem;
    font-weight: 700;
    color: #0f172a;
    display: block;
}

/* Crypto Proof Box */
.crypto-proof-box {
    background: #0f172a;
    color: white;
    padding: 1.25rem;
    border-radius: 12px;
    margin-bottom: 1.25rem;
}

.proof-header {
    display: flex;
    justify-content: space-between;
    font-size: 0.85rem;
    font-weight: 600;
    color: #94a3b8;
    margin-bottom: 0.5rem;
}

.verified-tag {
    color: #4ade80;
}

.hash-code {
    font-family: 'JetBrains Mono', monospace;
    font-size: 0.85rem;
    color: #38bdf8;
    word-break: break-all;
    line-height: 1.4;
}

/* AI Assessment Box */
.ai-assessment-box {
    background: #eff6ff;
    border: 1px solid #bfdbfe;
    border-radius: 12px;
    padding: 1.25rem;
    margin-bottom: 1.25rem;
}

.ai-box-header {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    margin-bottom: 0.5rem;
}

.ai-icon {
    font-size: 1.25rem;
}

.ai-badge {
    padding: 0.25rem 0.6rem;
    border-radius: 6px;
    font-size: 0.75rem;
    font-weight: 700;
    margin-left: 0.5rem;
}

.ai-badge-low {
    background: #dcfce7;
    color: #15803d;
}

.ai-badge-critical {
    background: #fee2e2;
    color: #b91c1c;
}

.ai-box-text {
    font-size: 0.9rem;
    color: #1e3a8a;
    line-height: 1.5;
}

.result-footer {
    display: flex;
    justify-content: space-between;
    font-size: 0.8rem;
    color: #64748b;
    padding-top: 1rem;
    border-top: 1px solid var(--border);
}

/* Stats Section */
.stats-section {
    background: white;
    padding: 3rem 1.5rem;
    border-bottom: 1px solid var(--border);
}

.stats-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 1.5rem;
    max-width: 1200px;
    margin: 0 auto;
}

.stat-card {
    background: #f8fafc;
    border: 1px solid var(--border);
    border-radius: 16px;
    padding: 1.75rem;
    text-align: center;
    transition: transform 0.2s, box-shadow 0.2s;
}

.stat-card:hover {
    transform: translateY(-3px);
    box-shadow: var(--shadow-md);
}

.stat-icon {
    font-size: 2rem;
    margin-bottom: 0.5rem;
}

.stat-number {
    font-size: 2.25rem;
    font-weight: 800;
    color: #0f172a;
    line-height: 1;
    margin-bottom: 0.35rem;
}

.stat-title {
    font-size: 0.95rem;
    font-weight: 700;
    color: #334155;
    margin-bottom: 0.2rem;
}

.stat-sub {
    font-size: 0.78rem;
    color: #64748b;
}

/* How It Works Section */
.how-it-works-section {
    padding: 4.5rem 1.5rem;
    background: #f8fafc;
}

.section-header {
    text-align: center;
    max-width: 700px;
    margin: 0 auto 3rem;
}

.section-tag {
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-weight: 800;
    color: var(--primary);
    background: #eff6ff;
    padding: 0.3rem 0.8rem;
    border-radius: 9999px;
    display: inline-block;
    margin-bottom: 0.75rem;
}

.section-title {
    font-size: 2.25rem;
    font-weight: 800;
    color: #0f172a;
    letter-spacing: -0.02em;
    margin-bottom: 0.75rem;
}

.section-subtitle {
    font-size: 1.05rem;
    color: #64748b;
    line-height: 1.5;
}

.steps-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 2rem;
    max-width: 1200px;
    margin: 0 auto;
}

.step-card {
    background: white;
    border-radius: 16px;
    padding: 2rem;
    border: 1px solid var(--border);
    box-shadow: var(--shadow-sm);
    position: relative;
    transition: transform 0.2s;
}

.step-card:hover {
    transform: translateY(-4px);
    box-shadow: var(--shadow-lg);
}

.step-badge {
    position: absolute;
    top: 1.25rem;
    right: 1.25rem;
    font-size: 0.75rem;
    font-weight: 800;
    background: #e0e7ff;
    color: #3730a3;
    padding: 0.25rem 0.6rem;
    border-radius: 6px;
}

.step-icon {
    font-size: 2.5rem;
    margin-bottom: 1.25rem;
}

.step-title {
    font-size: 1.25rem;
    font-weight: 800;
    color: #0f172a;
    margin-bottom: 0.5rem;
}

.step-desc {
    color: #64748b;
    font-size: 0.95rem;
    line-height: 1.6;
}

/* Blockchain & Features Sections */
.blockchain-section, .features-section {
    padding: 4.5rem 1.5rem;
}

.blockchain-section {
    background: white;
}

.blockchain-card {
    max-width: 1200px;
    margin: 0 auto;
    background: #f8fafc;
    border-radius: 16px;
    border: 1px solid var(--border);
    box-shadow: var(--shadow-sm);
    overflow: hidden;
}

.blockchain-card-header {
    padding: 1.25rem 1.75rem;
    background: white;
    border-bottom: 1px solid var(--border);
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.table-responsive {
    overflow-x: auto;
}

.blockchain-table, .data-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.88rem;
    text-align: left;
}

.blockchain-table th, .data-table th {
    background: #f1f5f9;
    padding: 0.9rem 1.25rem;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #475569;
    font-weight: 700;
    border-bottom: 1px solid var(--border);
}

.blockchain-table td, .data-table td {
    padding: 1rem 1.25rem;
    border-bottom: 1px solid var(--border);
    color: #1e293b;
}

.blockchain-table tr:hover, .data-table tr:hover {
    background: #f8fafc;
}

.features-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 2rem;
    max-width: 1200px;
    margin: 0 auto;
}

.feature-card {
    background: white;
    border: 1px solid var(--border);
    border-radius: 16px;
    padding: 2rem;
    box-shadow: var(--shadow-sm);
    transition: transform 0.2s, box-shadow 0.2s;
    display: flex;
    flex-direction: column;
}

.feature-card:hover {
    transform: translateY(-4px);
    box-shadow: var(--shadow-lg);
}

.feature-icon {
    font-size: 2.25rem;
    margin-bottom: 1rem;
}

.feature-card h3 {
    font-size: 1.2rem;
    font-weight: 800;
    color: #0f172a;
    margin-bottom: 0.5rem;
}

.feature-card p {
    color: #64748b;
    font-size: 0.95rem;
    line-height: 1.6;
    margin-bottom: 1.25rem;
    flex: 1;
}

.feature-pill {
    align-self: flex-start;
    background: #eff6ff;
    color: #2563eb;
    font-size: 0.75rem;
    font-weight: 700;
    padding: 0.25rem 0.65rem;
    border-radius: 9999px;
}

/* Floating AI Chat Assistant Widget */
.ai-widget-container {
    position: fixed;
    bottom: 2rem;
    right: 2rem;
    z-index: 1000;
}

.ai-floating-btn {
    background: linear-gradient(135deg, #2563eb, #6366f1);
    color: white;
    border: none;
    border-radius: 9999px;
    padding: 0.85rem 1.4rem;
    display: flex;
    align-items: center;
    gap: 0.6rem;
    font-weight: 700;
    font-size: 0.95rem;
    cursor: pointer;
    box-shadow: 0 10px 25px rgba(37, 99, 235, 0.4);
    transition: all 0.2s;
    position: relative;
}

.ai-floating-btn:hover {
    transform: scale(1.05);
}

.ai-chat-window {
    position: absolute;
    bottom: 4rem;
    right: 0;
    width: 380px;
    height: 520px;
    background: white;
    border-radius: 20px;
    box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.25);
    border: 1px solid var(--border);
    display: flex;
    flex-direction: column;
    overflow: hidden;
    animation: fadeIn 0.2s ease-out;
}

.ai-chat-header {
    background: #0f172a;
    color: white;
    padding: 1rem 1.25rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.ai-header-info {
    display: flex;
    align-items: center;
    gap: 0.75rem;
}

.ai-avatar {
    font-size: 1.5rem;
}

.ai-online-status {
    display: block;
    font-size: 0.7rem;
    color: #4ade80;
}

.ai-close-btn {
    background: none;
    border: none;
    color: #94a3b8;
    font-size: 1.2rem;
    cursor: pointer;
}

.ai-chat-messages {
    flex: 1;
    padding: 1rem;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    background: #f8fafc;
}

.ai-message {
    padding: 0.75rem 1rem;
    border-radius: 12px;
    font-size: 0.88rem;
    line-height: 1.5;
    max-width: 90%;
}

.ai-bot {
    background: white;
    color: #0f172a;
    border: 1px solid var(--border);
    align-self: flex-start;
}

.ai-user {
    background: var(--primary);
    color: white;
    align-self: flex-end;
}

.ai-quick-prompts {
    padding: 0.5rem 1rem;
    display: flex;
    gap: 0.5rem;
    overflow-x: auto;
    background: white;
    border-top: 1px solid var(--border);
}

.ai-quick-prompts button {
    white-space: nowrap;
    background: #f1f5f9;
    border: 1px solid var(--border);
    padding: 0.3rem 0.6rem;
    border-radius: 12px;
    font-size: 0.75rem;
    cursor: pointer;
    color: #334155;
}

.ai-quick-prompts button:hover {
    background: #e2e8f0;
}

.ai-chat-input-row {
    padding: 0.75rem 1rem;
    background: white;
    border-top: 1px solid var(--border);
    display: flex;
    gap: 0.5rem;
}

.ai-chat-input-row input {
    flex: 1;
    padding: 0.6rem 0.9rem;
    border: 1px solid var(--border);
    border-radius: 8px;
    font-size: 0.85rem;
    outline: none;
}

/* Dashboard Specific Styles */
.dashboard-main {
    max-width: 1200px;
    margin: 2rem auto;
    padding: 0 1.5rem;
    flex: 1;
}

.dash-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 2rem;
    flex-wrap: wrap;
    gap: 1rem;
}

.dash-title {
    font-size: 1.85rem;
    font-weight: 800;
    color: #0f172a;
}

.dash-subtitle {
    font-size: 0.95rem;
    color: #64748b;
    margin-top: 0.25rem;
}

.dash-tabs {
    display: flex;
    gap: 0.5rem;
    border-bottom: 2px solid var(--border);
    margin-bottom: 2rem;
    overflow-x: auto;
}

.dash-tab-btn {
    padding: 0.75rem 1.25rem;
    background: none;
    border: none;
    border-bottom: 3px solid transparent;
    font-weight: 700;
    font-size: 0.92rem;
    color: #64748b;
    cursor: pointer;
    transition: all 0.2s;
    white-space: nowrap;
}

.dash-tab-btn:hover {
    color: var(--primary);
}

.dash-tab-btn.active {
    color: var(--primary);
    border-bottom-color: var(--primary);
}

.dash-card {
    background: white;
    border-radius: 16px;
    border: 1px solid var(--border);
    box-shadow: var(--shadow-sm);
    padding: 1.75rem;
}

.dash-card-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1.25rem;
    padding-bottom: 1rem;
    border-bottom: 1px solid var(--border);
}

.form-label {
    display: block;
    font-size: 0.85rem;
    font-weight: 700;
    color: #334155;
    margin-bottom: 0.35rem;
}

.ai-scan-output-card {
    background: #f8fafc;
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 1.5rem;
    margin-top: 1rem;
}

.ai-checks-box {
    background: white;
    padding: 1rem;
    border-radius: 8px;
    border: 1px solid var(--border);
}

/* Footer */
.footer {
    background: #0f172a;
    color: #94a3b8;
    margin-top: auto;
}

.footer-content {
    max-width: 1200px;
    margin: 0 auto;
    padding: 3rem 1.5rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 1.5rem;
}

.footer-brand {
    display: flex;
    align-items: center;
    gap: 1rem;
}

.footer-links {
    display: flex;
    gap: 1.5rem;
    flex-wrap: wrap;
}

.footer-links a {
    color: #cbd5e1;
    text-decoration: none;
    font-size: 0.9rem;
    transition: color 0.2s;
}

.footer-links a:hover {
    color: #38bdf8;
}

.footer-bottom {
    border-top: 1px solid rgba(255, 255, 255, 0.08);
    padding: 1.25rem 1.5rem;
}

/* Responsive Media Queries */
@media (max-width: 768px) {
    .hero-title {
        font-size: 2.1rem;
    }
    .input-group {
        flex-direction: column;
    }
    .nav-toggle {
        display: flex;
    }
