package com.devops.qvs.service;

import com.devops.qvs.dto.QualificationRequest;
import com.devops.qvs.dto.QualificationResponse;
import com.devops.qvs.exception.BadRequestException;
import com.devops.qvs.exception.ResourceNotFoundException;
import com.devops.qvs.model.Institution;
import com.devops.qvs.model.Qualification;
import com.devops.qvs.model.QualificationStatus;
import com.devops.qvs.repository.InstitutionRepository;
import com.devops.qvs.repository.QualificationRepository;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.time.LocalDate;
import java.util.List;
import java.util.Optional;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
@DisplayName("Unit Tests: Qualification Management Service")
class QualificationServiceTest {

    @Mock
    private QualificationRepository qualificationRepository;

    @Mock
    private InstitutionRepository institutionRepository;

    @Mock
    private CryptoHashService cryptoHashService;

    @Mock
    private BlockchainLedgerService blockchainLedgerService;

    @InjectMocks
    private QualificationService qualificationService;

    private Institution sampleInstitution;
    private Qualification sampleQualification;
    private QualificationRequest sampleRequest;

    @BeforeEach
    void setUp() {
        sampleInstitution = Institution.builder()
                .id(1L)
                .name("Tech University")
                .institutionCode("TU-01")
                .build();

        sampleQualification = Qualification.builder()
                .id(100L)
                .certificateNumber("QVS-2024-ENG-01")
                .studentFullName("Jane Doe")
                .studentIdNumber("STU-123")
                .awardTitle("BSc Software Engineering")
                .majorSpecialization("DevOps")
                .classification("First Class")
                .awardDate(LocalDate.of(2024, 6, 1))
                .institution(sampleInstitution)
                .status(QualificationStatus.ACTIVE)
                .digitalFingerprint("sample_mock_hash_12345")
                .build();

        sampleRequest = QualificationRequest.builder()
                .certificateNumber("QVS-2024-ENG-01")
                .studentFullName("Jane Doe")
                .studentIdNumber("STU-123")
                .awardTitle("BSc Software Engineering")
                .majorSpecialization("DevOps")
                .classification("First Class")
                .awardDate(LocalDate.of(2024, 6, 1))
                .institutionId(1L)
                .build();
    }

    @Test
    @DisplayName("Should successfully register qualification with hash generation")
    void testRegisterQualificationSuccess() {
        when(qualificationRepository.existsByCertificateNumber(sampleRequest.getCertificateNumber())).thenReturn(false);
        when(institutionRepository.findById(1L)).thenReturn(Optional.of(sampleInstitution));
        when(cryptoHashService.generateFingerprint(anyString(), anyString(), anyString(), anyString(), anyString(), any(LocalDate.class)))
                .thenReturn("generated_hash_abc");
        when(qualificationRepository.save(any(Qualification.class))).thenReturn(sampleQualification);

        QualificationResponse response = qualificationService.registerQualification(sampleRequest);

        assertNotNull(response);
        assertEquals("QVS-2024-ENG-01", response.getCertificateNumber());
        assertEquals("Jane Doe", response.getStudentFullName());
        verify(qualificationRepository).save(any(Qualification.class));
    }

    @Test
    @DisplayName("Should throw BadRequestException if certificate number already registered")
    void testRegisterDuplicateCertificateThrowsException() {
        when(qualificationRepository.existsByCertificateNumber(sampleRequest.getCertificateNumber())).thenReturn(true);

        assertThrows(BadRequestException.class, () -> qualificationService.registerQualification(sampleRequest));
        verify(qualificationRepository, never()).save(any());
    }

    @Test
    @DisplayName("Should retrieve qualification by certificate number")
    void testGetByCertificateNumberSuccess() {
        when(qualificationRepository.findByCertificateNumber("QVS-2024-ENG-01")).thenReturn(Optional.of(sampleQualification));

        QualificationResponse response = qualificationService.getByCertificateNumber("QVS-2024-ENG-01");

        assertNotNull(response);
        assertEquals("Jane Doe", response.getStudentFullName());
    }

    @Test
    @DisplayName("Should throw ResourceNotFoundException if certificate not found")
    void testGetByCertificateNumberNotFound() {
        when(qualificationRepository.findByCertificateNumber("UNKNOWN")).thenReturn(Optional.empty());

        assertThrows(ResourceNotFoundException.class, () -> qualificationService.getByCertificateNumber("UNKNOWN"));
    }

    @Test
    @DisplayName("Should revoke qualification with valid reason")
    void testRevokeQualification() {
        when(qualificationRepository.findById(100L)).thenReturn(Optional.of(sampleQualification));
        when(qualificationRepository.save(any(Qualification.class))).thenAnswer(i -> i.getArgument(0));

        QualificationResponse response = qualificationService.revokeQualification(100L, "Disciplinary action");

        assertNotNull(response);
        assertEquals(QualificationStatus.REVOKED, response.getStatus());
        assertEquals("Disciplinary action", response.getRevocationReason());
    }

    @Test
    @DisplayName("Should search qualifications by keyword")
    void testSearchQualifications() {
        when(qualificationRepository.searchQualifications("Jane")).thenReturn(List.of(sampleQualification));

        List<QualificationResponse> results = qualificationService.search("Jane");

        assertEquals(1, results.size());
        assertEquals("Jane Doe", results.get(0).getStudentFullName());
    }
}

package com.devops.qvs.service;

import com.devops.qvs.dto.BlockDto;
import com.devops.qvs.model.Block;
import com.devops.qvs.repository.BlockRepository;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.time.LocalDateTime;
import java.util.List;
import java.util.Optional;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
@DisplayName("Unit Tests: Blockchain Credential Ledger Service")
class BlockchainLedgerServiceTest {

    @Mock
    private BlockRepository blockRepository;

    @InjectMocks
    private BlockchainLedgerService blockchainLedgerService;

    private Block genesisBlock;
    private Block blockOne;

    @BeforeEach
    void setUp() {
        LocalDateTime now = LocalDateTime.now();

        String genesisHash = blockchainLedgerService.calculateBlockHash(
                0L, now, "GENESIS-ROOT", "genesis_payload_hash", BlockchainLedgerService.GENESIS_PREV_HASH, 42L
        );

        genesisBlock = Block.builder()
                .id(1L)
                .blockIndex(0L)
                .timestamp(now)
                .certificateNumber("GENESIS-ROOT")
                .dataHash("genesis_payload_hash")
                .previousHash(BlockchainLedgerService.GENESIS_PREV_HASH)
                .blockHash(genesisHash)
                .nonce(42L)
                .actionType("GENESIS")
                .minedBy("QVS-GENESIS-NODE")
                .build();

        String blockOneHash = blockchainLedgerService.calculateBlockHash(
                1L, now.plusMinutes(1), "QVS-2024-BSC-8891", "data_hash_sarah", genesisHash, 100L
        );

        blockOne = Block.builder()
                .id(2L)
                .blockIndex(1L)
                .timestamp(now.plusMinutes(1))
                .certificateNumber("QVS-2024-BSC-8891")
                .dataHash("data_hash_sarah")
                .previousHash(genesisHash)
                .blockHash(blockOneHash)
                .nonce(100L)
                .actionType("ISSUE")
                .minedBy("TECH-UNI-NODE")
                .build();
    }

    @Test
    @DisplayName("Should initialize genesis block when repository is empty")
    void testInitGenesisBlockWhenEmpty() {
        when(blockRepository.count()).thenReturn(0L);

        blockchainLedgerService.initGenesisBlock();

        verify(blockRepository).save(any(Block.class));
    }

    @Test
    @DisplayName("Should mine a new block linked to the latest block hash")
    void testMineBlock() {
        when(blockRepository.findTopByOrderByBlockIndexDesc()).thenReturn(Optional.of(genesisBlock));
        when(blockRepository.save(any(Block.class))).thenAnswer(invocation -> invocation.getArgument(0));

        Block newBlock = blockchainLedgerService.mineBlock("QVS-2024-TEST-001", "some_payload_hash", "ISSUE", "TEST_NODE");

        assertNotNull(newBlock);
        assertEquals(1L, newBlock.getBlockIndex());
        assertEquals(genesisBlock.getBlockHash(), newBlock.getPreviousHash());
        assertEquals("QVS-2024-TEST-001", newBlock.getCertificateNumber());
        verify(blockRepository).save(any(Block.class));
    }

    @Test
    @DisplayName("Should return true when validating a healthy, un-tampered chain")
    void testValidateChainSuccess() {
        when(blockRepository.findAllByOrderByBlockIndexAsc()).thenReturn(List.of(genesisBlock, blockOne));

        boolean valid = blockchainLedgerService.validateChain();

        assertTrue(valid);
    }

    @Test
    @DisplayName("Should detect tampering when a block payload hash has been modified")
    void testValidateChainFailsOnTampering() {
        Block tamperedBlockOne = Block.builder()
                .id(2L)
                .blockIndex(1L)
                .timestamp(blockOne.getTimestamp())
                .certificateNumber("QVS-2024-BSC-8891")
                .dataHash("TAMPERED_PAYLOAD_HASH")
                .previousHash(genesisBlock.getBlockHash())
                .blockHash(blockOne.getBlockHash()) // keeping original hash despite payload change
                .nonce(100L)
                .actionType("ISSUE")
                .minedBy("FORGED-NODE")
                .build();

        when(blockRepository.findAllByOrderByBlockIndexAsc()).thenReturn(List.of(genesisBlock, tamperedBlockOne));

        boolean valid = blockchainLedgerService.validateChain();

        assertFalse(valid);
    }

    @Test
    @DisplayName("Should retrieve all blocks as DTOs")
    void testGetAllBlocks() {
        when(blockRepository.findAllByOrderByBlockIndexAsc()).thenReturn(List.of(genesisBlock, blockOne));

        List<BlockDto> dtos = blockchainLedgerService.getAllBlocks();

        assertEquals(2, dtos.size());
        assertEquals("GENESIS-ROOT", dtos.get(0).getCertificateNumber());
        assertEquals("QVS-2024-BSC-8891", dtos.get(1).getCertificateNumber());
    }
}

package com.devops.qvs.service;

import com.devops.qvs.dto.AiAnalysisResultDto;
import com.devops.qvs.dto.AiChatRequest;
import com.devops.qvs.dto.AiChatResponse;
import com.devops.qvs.model.Institution;
import com.devops.qvs.model.Qualification;
import com.devops.qvs.model.QualificationStatus;
import com.devops.qvs.repository.QualificationRepository;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.time.LocalDate;
import java.util.Optional;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
@DisplayName("Unit Tests: Agentic AI Fraud Detection & Assistant Service")
class AiFraudDetectionServiceTest {

    @Mock
    private QualificationRepository qualificationRepository;

    @Mock
    private CryptoHashService cryptoHashService;

    @InjectMocks
    private AiFraudDetectionService aiFraudDetectionService;

    private Institution sampleInstitution;
    private Qualification genuineQual;
    private Qualification revokedQual;

    @BeforeEach
    void setUp() {
        sampleInstitution = Institution.builder()
                .id(1L)
                .name("National Institute of Tech")
                .institutionCode("NIT-001")
                .active(true)
                .build();

        genuineQual = Qualification.builder()
                .id(101L)
                .certificateNumber("QVS-2024-BSC-8891")
                .studentFullName("Sarah Jenkins")
                .studentIdNumber("STU-990142")
                .awardTitle("Bachelor of Science in Software Engineering")
                .majorSpecialization("DevOps")
                .classification("First Class Honours")
                .awardDate(LocalDate.of(2024, 7, 15))
                .institution(sampleInstitution)
                .status(QualificationStatus.ACTIVE)
                .digitalFingerprint("valid_hash_12345")
                .build();

        revokedQual = Qualification.builder()
                .id(102L)
                .certificateNumber("QVS-2022-DIP-1109")
                .studentFullName("Marcus Vance")
                .studentIdNumber("STU-772911")
                .awardTitle("Diploma in Enterprise Systems")
                .majorSpecialization("Infrastructure")
                .classification("Second Class")
                .awardDate(LocalDate.of(2022, 6, 30))
                .institution(sampleInstitution)
                .status(QualificationStatus.REVOKED)
                .revocationReason("Disciplinary misconduct")
                .digitalFingerprint("revoked_hash_99999")
                .build();
    }

    @Test
    @DisplayName("Should assign LOW risk and 100 authenticity score for genuine valid certificate")
    void testAnalyzeGenuineCertificate() {
        when(qualificationRepository.findByCertificateNumber("QVS-2024-BSC-8891"))
                .thenReturn(Optional.of(genuineQual));
        when(cryptoHashService.verifyFingerprint(anyString(), anyString(), anyString(), anyString(), anyString(), any(LocalDate.class), anyString()))
                .thenReturn(true);

        AiAnalysisResultDto result = aiFraudDetectionService.analyzeCertificate("QVS-2024-BSC-8891");

        assertNotNull(result);
        assertEquals("LOW", result.getRiskLevel());
        assertEquals(100, result.getAuthenticityScore());
        assertTrue(result.getPassedChecks().size() >= 3);
        assertTrue(result.getAnomalyFlags().isEmpty());
    }

    @Test
    @DisplayName("Should assign HIGH/CRITICAL risk when certificate is revoked")
    void testAnalyzeRevokedCertificate() {
        when(qualificationRepository.findByCertificateNumber("QVS-2022-DIP-1109"))
                .thenReturn(Optional.of(revokedQual));
        when(cryptoHashService.verifyFingerprint(anyString(), anyString(), anyString(), anyString(), anyString(), any(LocalDate.class), anyString()))
                .thenReturn(true);

        AiAnalysisResultDto result = aiFraudDetectionService.analyzeCertificate("QVS-2022-DIP-1109");

        assertNotNull(result);
        assertTrue(result.getRiskLevel().equals("HIGH") || result.getRiskLevel().equals("CRITICAL"));
        assertTrue(result.getAuthenticityScore() < 50);
        assertTrue(result.getAnomalyFlags().stream().anyMatch(f -> f.contains("REVOKED")));
    }

    @Test
    @DisplayName("Should assign CRITICAL risk and 0 score when certificate does not exist in registry")
    void testAnalyzeNonExistentCertificate() {
        when(qualificationRepository.findByCertificateNumber("FAKE-999"))
                .thenReturn(Optional.empty());

        AiAnalysisResultDto result = aiFraudDetectionService.analyzeCertificate("FAKE-999");

        assertNotNull(result);
        assertEquals("CRITICAL", result.getRiskLevel());
        assertEquals(0, result.getAuthenticityScore());
    }

    @Test
    @DisplayName("Should respond intelligently to AI conversational user queries")
    void testChatWithAgent() {
        AiChatResponse response = aiFraudDetectionService.processUserQuery(
                AiChatRequest.builder().message("How do I verify a certificate?").build()
        );

        assertNotNull(response);
        assertEquals("SUCCESS", response.getStatus());
        assertTrue(response.getReply().contains("How to Verify"));
    }
}

